#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-outside-in.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
// verify-outside-in — consolidated outside-in gate (5 sub-checks).
//
// One file, five self-contained sub-checks. Each no-ops green when its trigger
// shape is absent, then enforces its own rule with its own exact exit codes +
// stderr/stdout messages. Each lives in its own function scope (closure) so the
// five gates' local names (NAME / ok / srcRoot / repoRoot / violations …) never
// collide.
//
//   - journeys        USER_JOURNEYS.yaml: the outside-in journey catalog exists,
//                     every journey proves outside-in origin (provenance), and
//                     journeys ↔ flows reconcile in BOTH directions (+ blind
//                     traversal audit reachable). No-op when no src/features AND
//                     no docs/journeys/.
//   - labs            LABS.yaml: when labs is enabled the flow<->labs map
//                     reconciles both directions and no flow-affecting feedback
//                     is left open. No-op when labs not enabled + no docs/labs/.
//   - requirements    REQUIREMENTS_CONTRACT.yaml: a repo building features has
//                     user-locked requirements; every assumption-ledger entry
//                     carries a derivation. No-op when no src/features.
//   - site-blueprint  SITE_BLUEPRINT.yaml: page-tier surfaces may only be coded
//                     after a complete, locked, AIRTIGHT docs/site/ blueprint.
//                     No-op when ui_discipline: none, or no page-tier specs AND
//                     no locked blueprint.
//   - api-first       API_FIRST.yaml: page-tier UI is refused until every flow is
//                     E2E-mapped + mermaid-diagrammed in
//                     docs/site/MECHANICAL_COMPLETE.yaml. No-op when no page-tier
//                     source, or ui_discipline: none.
//
// Usage:
//   node verify-outside-in.mjs                       run all five (fail iff any fails)
//   node verify-outside-in.mjs --check journeys
//   node verify-outside-in.mjs --check labs
//   node verify-outside-in.mjs --check requirements
//   node verify-outside-in.mjs --check site-blueprint
//   node verify-outside-in.mjs --check api-first
//   node verify-outside-in.mjs [<src-root>]          optional positional src root (default "src")
//
// Exit: 0 when every selected check is green; 1 when any check fails; 2 on an
// unknown --check name.
//
// Root resolution: each sub-check locates the repo root via a `.git` marker
// relative to process.cwd() (site-blueprint via `git rev-parse --show-toplevel`
// with a cwd fallback). Spec/flow CONTENT reads route through lib/load-spec.mjs
// (loadSpec); when the project `yaml` package is unavailable each falls back to
// the dep-free line regex — identical result for top-level specs. Existence-only
// checks stay direct.

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { execSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { loadSpec } from "../lib/load-spec.mjs";

// ════════════════════════════════════════════════════════════════════════
// CHECK 1 — journeys (USER_JOURNEYS.yaml)
// ════════════════════════════════════════════════════════════════════════

function checkJourneys(srcArg) {
  const GREEN = "\x1b[32m"; const RED = "\x1b[31m"; const RESET = "\x1b[0m";
  const NAME = "verify-journeys";
  const ok = (m) => { process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${m}\n`); return 0; };

  const srcRoot = path.resolve(process.cwd(), srcArg || "src");
  const repoRoot = ["..", "../..", "."].map((u) => path.resolve(process.cwd(), u)).find((p) => fs.existsSync(path.join(p, ".git"))) || path.resolve(process.cwd(), "../..");
  const journeysDir = path.join(repoRoot, "docs", "journeys");
  const hasFeatures = fs.existsSync(path.join(srcRoot, "features"));
  const hasJourneys = fs.existsSync(journeysDir);

  if (!hasFeatures && !hasJourneys) return ok("no src/features and no docs/journeys yet — nothing to gate.");

  const violations = [];
  const index = path.join(journeysDir, "00-INDEX.md");
  const blindDir = path.join(journeysDir, "blind-traversal");
  const blindIndex = path.join(blindDir, "00-INDEX.md");

  if (hasFeatures && !fs.existsSync(index)) {
    violations.push(`features exist but ${path.relative(repoRoot, index)} is missing — the outside-in journey catalog + bidirectional map must precede code (USER_JOURNEYS.yaml)`);
  }

  if (hasFeatures && !fs.existsSync(blindIndex)) {
    violations.push(`features exist but ${path.relative(repoRoot, blindIndex)} is missing — the blind traversal audit (domain-only goal walked using ONLY docs/flows) must run over the reconciled set (USER_JOURNEYS.yaml.blind_traversal_audit)`);
  } else if (fs.existsSync(blindIndex)) {
    const t = fs.readFileSync(blindIndex, "utf8");
    for (const [key, label] of [
      ["unreachable_goals", "each names a flow the docs cannot walk a stranger through"],
      ["priority_goals_uncovered", "the repeated audit must reach every most-likely / most-important / high-traffic goal before it stops"],
    ]) {
      const m = t.match(new RegExp(`${key}:\\s*(\\d+)`));
      if (!m) {
        violations.push(`blind-traversal/00-INDEX.md missing the '${key}: <n>' data line (USER_JOURNEYS.yaml.blind_traversal_audit)`);
      } else if (Number(m[1]) !== 0) {
        violations.push(`blind-traversal/00-INDEX.md reports ${key}: ${m[1]} — must be 0 (${label}). The verdict is NO.`);
      }
    }
  }

  if (hasJourneys) {
    const journeyFiles = fs.readdirSync(journeysDir).filter((f) => /^J-\d{3}-.+\.md$/.test(f));
    if (journeyFiles.length === 0) {
      violations.push("docs/journeys/ exists but holds no J-<NNN>-<slug>.md journey file");
    }
    for (const f of journeyFiles) {
      const t = fs.readFileSync(path.join(journeysDir, f), "utf8");
      if (!/not_derived_from_our_flows:\s*true/.test(t)) {
        violations.push(`${f}: missing 'not_derived_from_our_flows: true' — a journey back-derived from our own flows is non-compliant (USER_JOURNEYS.yaml.user_journey.provenance)`);
      }
      if (!/inspired_by:\s*\S/.test(t) && !/inspired_by:\s*\n\s*-\s*\S/.test(t)) {
        violations.push(`${f}: empty or missing 'inspired_by' provenance — every journey names the peer apps/domain conventions that model its intent`);
      }
    }

    if (fs.existsSync(index)) {
      const t = fs.readFileSync(index, "utf8");
      for (const [key, label] of [["unmapped_journeys", "forward: journey step with no flow = missing capability"], ["orphan_flows", "reverse: flow with no journey = orphan feature (HARD RED)"]]) {
        const m = t.match(new RegExp(`${key}:\\s*(\\d+)`));
        if (!m) {
          violations.push(`00-INDEX.md missing the '${key}: <n>' reconciliation data line (${label})`);
        } else if (Number(m[1]) !== 0) {
          violations.push(`00-INDEX.md reports ${key}: ${m[1]} — must be 0 (${label}). The reconciliation verdict is NO.`);
        }
      }
    }
  }

  if (violations.length === 0) return ok("journey catalog present; provenance proven; journeys ↔ flows reconciled both directions; blind traversal audit reachable.");
  process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 2 — labs (LABS.yaml)
// ════════════════════════════════════════════════════════════════════════

function checkLabs(srcArg) {
  const GREEN = "\x1b[32m"; const RED = "\x1b[31m"; const RESET = "\x1b[0m";
  const NAME = "verify-labs";
  const ok = (m) => { process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${m}\n`); return 0; };

  const srcRoot = path.resolve(process.cwd(), srcArg || "src");
  void srcRoot;
  const repoRoot = ["..", "../..", "."].map((u) => path.resolve(process.cwd(), u)).find((p) => fs.existsSync(path.join(p, ".git"))) || path.resolve(process.cwd(), "../..");
  const labsCfg = path.join(repoRoot, ".standards", "labs.yaml");
  const labsDir = path.join(repoRoot, "docs", "labs");

  const cfgText = fs.existsSync(labsCfg) ? fs.readFileSync(labsCfg, "utf8") : "";
  const enabled = /enabled:\s*true/.test(cfgText);
  const hasLabsDir = fs.existsSync(labsDir);

  if (!enabled && !hasLabsDir) return ok("labs not enabled for this repo and no docs/labs/ — nothing to gate.");

  const violations = [];
  const index = path.join(labsDir, "00-INDEX.md");

  if (!fs.existsSync(index)) {
    violations.push(`labs is active but ${path.relative(repoRoot, index)} is missing — the flow<->labs bidirectional map must exist (LABS.yaml.flow_labs_mapping)`);
  } else {
    const t = fs.readFileSync(index, "utf8");
    for (const [key, label] of [
      ["unbacked_surfaces", "reverse: a labs surface with no flow = red"],
      ["uncovered_flows", "forward: a flow with no labs surface = red"],
    ]) {
      const m = t.match(new RegExp(`${key}:\\s*(\\d+)`));
      if (!m) {
        violations.push(`labs/00-INDEX.md missing the '${key}: <n>' data line (${label})`);
      } else if (Number(m[1]) !== 0) {
        violations.push(`labs/00-INDEX.md reports ${key}: ${m[1]} — must be 0 (${label}). The verdict is NO.`);
      }
    }
  }

  const feedbackDir = path.join(labsDir, "feedback");
  if (fs.existsSync(feedbackDir)) {
    for (const f of fs.readdirSync(feedbackDir).filter((f) => f.endsWith(".yaml"))) {
      const t = fs.readFileSync(path.join(feedbackDir, f), "utf8");
      // a flow-affecting item still open blocks promotion / product-feed
      if (/triage:\s*flow\b/.test(t) && /status:\s*open\b/.test(t)) {
        violations.push(`labs/feedback/${f}: a triage:flow item is status:open — flows must be updated (and re-gated) before promotion / product-feed (LABS.yaml.feedback_protocol.gate)`);
      }
    }
  }

  if (violations.length === 0) return ok("labs active; flow<->labs reconciled both directions; no open flow-affecting feedback.");
  process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 3 — requirements (REQUIREMENTS_CONTRACT.yaml)
// ════════════════════════════════════════════════════════════════════════

function checkRequirements(srcArg) {
  const GREEN = "\x1b[32m"; const RED = "\x1b[31m"; const RESET = "\x1b[0m";
  const NAME = "verify-requirements";
  const ok = (m) => { process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${m}\n`); return 0; };

  const srcRoot = path.resolve(process.cwd(), srcArg || "src");
  if (!fs.existsSync(path.join(srcRoot, "features"))) return ok("no src/features yet — nothing autonomous to gate.");

  const repoRoot = ["..", "../..", "."].map((u) => path.resolve(process.cwd(), u)).find((p) => fs.existsSync(path.join(p, ".git"))) || path.resolve(process.cwd(), "../..");
  const req = path.join(repoRoot, "docs", "requirements", "REQUIREMENTS.md");
  const violations = [];

  if (!fs.existsSync(req)) {
    violations.push(`features exist but ${path.relative(repoRoot, req)} is missing — autonomous building requires user-locked requirements (REQUIREMENTS_CONTRACT.yaml)`);
  } else if (!/<!--\s*requirements-locked:\s*\d{4}-\d{2}-\d{2}\s+by:user\s*-->/.test(fs.readFileSync(req, "utf8"))) {
    violations.push("REQUIREMENTS.md lacks the '<!-- requirements-locked: YYYY-MM-DD by:user -->' marker — ONLY the user locks requirements");
  }

  const ledger = path.join(repoRoot, "docs", "requirements", "ASSUMPTIONS.yaml");
  if (fs.existsSync(ledger)) {
    const t = fs.readFileSync(ledger, "utf8");
    const entries = t.split(/^\s*-\s+date:/m).slice(1);
    entries.forEach((e, i) => {
      const m = e.match(/derived_from:\s*(.+)/);
      if (!m || !m[1].trim() || /^['"]?\s*['"]?$/.test(m[1].trim())) {
        violations.push(`ASSUMPTIONS.yaml entry ${i + 1} has no derived_from citation — an underivable assumption is a STOP-and-ask, not a ledger entry`);
      }
    });
  }

  if (violations.length === 0) return ok("requirements user-locked; assumption ledger derivations present.");
  process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 4 — site-blueprint (SITE_BLUEPRINT.yaml)
// ════════════════════════════════════════════════════════════════════════

function checkSiteBlueprint(srcArg) {
  const { readFileSync, existsSync, readdirSync, statSync } = fs;
  const { join, relative } = path;

  const RULE_ID = "verify-site-blueprint";
  const SRC_ROOT = srcArg || "src";
  const CWD = process.cwd();

  let gitRoot = CWD;
  try {
    gitRoot = execSync("git rev-parse --show-toplevel", { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
  } catch {
    /* not a git repo — treat cwd as root */
  }

  const LOCK_MARKER = /<!--\s*blueprint-locked:\s*\d{4}-\d{2}-\d{2}\s+by:(user|agent)\s*-->/;
  const PLACEHOLDER = /\b(TBD|TODO)\b|<placeholder>/;
  const PAGE_DOC_SECTIONS = [
    "## Purpose", "## Route & access", "## Layout", "## Components", "## Data",
    "## State matrix", "## Interactions", "## Edge cases", "## Accessibility", "## Responsive",
  ];
  const FLOW_DOC_SECTIONS = [
    "## Actors & trigger", "## Preconditions", "## Happy path", "## Branches & failures",
    "## Postconditions", "## Scenario checklist",
  ];
  const violations = [];

  // Read a page-tier flag from a spec, routing through load-spec; fall back to
  // the dep-free line regex when the project `yaml` package is unavailable.
  const isPageSpec = (specPath) => {
    const loaded = loadSpec(path.dirname(specPath));
    if (loaded.ok && loaded.value && typeof loaded.value === "object") return loaded.value.tier === "page";
    return /^\s*tier:\s*page\b/m.test(readFileSync(specPath, "utf8"));
  };
  const specBlueprintDoc = (specPath) => {
    const loaded = loadSpec(path.dirname(specPath));
    if (loaded.ok && loaded.value && typeof loaded.value === "object") {
      return loaded.value.blueprint_doc != null ? String(loaded.value.blueprint_doc) : null;
    }
    const m = readFileSync(specPath, "utf8").match(/^\s*blueprint_doc:\s*(\S+)\s*$/m);
    return m ? m[1] : null;
  };

  // ---------- short-circuit: ui_discipline none ----------
  for (const dir of [CWD, gitRoot]) {
    const autonomyPath = join(dir, ".standards", "autonomy.yaml");
    if (existsSync(autonomyPath) && /^\s*ui_discipline:\s*none\b/m.test(readFileSync(autonomyPath, "utf8"))) {
      process.stdout.write(`✅ ${RULE_ID} — ui_discipline: none; n/a — non-UI project.\n`);
      return 0;
    }
  }

  // ---------- discover page-tier specs ----------
  const SKIP_DIRS = new Set(["node_modules", ".next", ".turbo", ".git", "coverage", "dist"]);
  function walk(dir, hits = []) {
    let entries;
    try { entries = readdirSync(dir); } catch { return hits; }
    for (const name of entries) {
      if (SKIP_DIRS.has(name)) continue;
      const p = join(dir, name);
      let st;
      try { st = statSync(p); } catch { continue; }
      if (st.isDirectory()) walk(p, hits);
      else if (name === "spec.yaml" && isPageSpec(p)) hits.push(p);
    }
    return hits;
  }
  const srcAbs = join(CWD, SRC_ROOT);
  const pageSpecs = existsSync(srcAbs) ? walk(srcAbs) : [];

  const bpRoot = join(gitRoot, "docs", "site");
  const indexPath = join(bpRoot, "00-INDEX.md");
  const locked = existsSync(indexPath) && LOCK_MARKER.test(readFileSync(indexPath, "utf8"));

  if (pageSpecs.length === 0 && !locked) {
    const note = existsSync(bpRoot)
      ? "blueprint present but not yet locked (in-progress planning); no page-tier specs — nothing gated."
      : `no page-tier specs under ${SRC_ROOT}/ and no blueprint; components/API work is not gated.`;
    process.stdout.write(`✅ ${RULE_ID} — ${note}\n`);
    return 0;
  }

  // ---------- page specs exist: lock is mandatory ----------
  if (pageSpecs.length > 0 && !locked) {
    violations.push(`page-tier specs exist but docs/site/00-INDEX.md lacks the lock marker <!-- blueprint-locked: YYYY-MM-DD by:user|agent -->`);
  }

  // ---------- helpers ----------
  function mdFiles(dir) {
    if (!existsSync(dir)) return [];
    return readdirSync(dir).filter((f) => f.endsWith(".md")).map((f) => join(dir, f));
  }
  const pagesDir = join(bpRoot, "pages");
  const flowsDir = join(bpRoot, "flows");
  const pageDocs = mdFiles(pagesDir);
  const flowDocs = mdFiles(flowsDir);
  const allDocs = [...mdFiles(bpRoot), ...pageDocs, ...flowDocs];
  const rel = (p) => relative(gitRoot, p);

  // ---------- airtightness suite (runs whenever locked) ----------
  if (locked) {
    // A1 core files
    const CORE = ["00-INDEX.md", "01-DESIGN-LANGUAGE.md", "02-ROUTES-AND-SHELL.md", "03-API-BINDINGS.md", "99-COVERAGE-MATRIX.md"];
    for (const f of CORE) {
      if (!existsSync(join(bpRoot, f))) violations.push(`A1: missing blueprint core file docs/site/${f}`);
    }

    // A2 placeholders
    for (const p of allDocs) {
      readFileSync(p, "utf8").split("\n").forEach((line, i) => {
        if (PLACEHOLDER.test(line)) violations.push(`A2: placeholder text in ${rel(p)}:${i + 1} — "${line.trim().slice(0, 60)}"`);
      });
    }

    // A3 template sections — all page docs + all flow docs
    for (const p of pageDocs) {
      const doc = readFileSync(p, "utf8");
      for (const sec of PAGE_DOC_SECTIONS) if (!doc.includes(sec)) violations.push(`A3: ${rel(p)} lacks "${sec}"`);
    }
    for (const p of flowDocs) {
      const doc = readFileSync(p, "utf8");
      for (const sec of FLOW_DOC_SECTIONS) if (!doc.includes(sec)) violations.push(`A3: ${rel(p)} lacks "${sec}"`);
    }

    const bindingsPath = join(bpRoot, "03-API-BINDINGS.md");
    const bindings = existsSync(bindingsPath) ? readFileSync(bindingsPath, "utf8") : "";

    // A4 GAP citations + A5 endpoint citations
    for (const p of [...pageDocs, ...flowDocs]) {
      const doc = readFileSync(p, "utf8");
      if (/GAP-NEW/.test(doc)) violations.push(`A4: ${rel(p)} contains draft marker GAP-NEW — assign a real GAP id in 03-API-BINDINGS.md`);
      for (const g of new Set([...doc.matchAll(/GAP-(\d+)/g)].map((m) => m[1]))) {
        if (!bindings.includes(`| GAP-${g} |`)) violations.push(`A4: ${rel(p)} cites GAP-${g} — no such row in 03-API-BINDINGS.md`);
      }
      for (const e of new Set([...doc.matchAll(/\/api\/v1\/[a-zA-Z0-9/_[\]{}|.-]+/g)].map((m) => m[0].replace(/[.,)`]+$/, "")))) {
        if (!bindings.includes(e)) violations.push(`A5: ${rel(p)} cites ${e} — not listed in 03-API-BINDINGS.md`);
      }
    }

    // A6 cross-references
    for (const p of allDocs) {
      const doc = readFileSync(p, "utf8");
      for (const m of new Set([...doc.matchAll(/\b(flows|pages)\/([a-z0-9_-]+\.md)/g)].map((x) => `${x[1]}/${x[2]}`))) {
        if (!existsSync(join(bpRoot, m))) violations.push(`A6: ${rel(p)} references ${m} — file does not exist`);
      }
    }

    // A7 coverage matrix
    const matrixPath = join(bpRoot, "99-COVERAGE-MATRIX.md");
    if (existsSync(matrixPath)) {
      const matrix = readFileSync(matrixPath, "utf8");
      if (!/^unmapped_stories:\s*0\s*$/m.test(matrix)) {
        violations.push(`A7: 99-COVERAGE-MATRIX.md lacks the literal terminal line "unmapped_stories: 0"`);
      }
      for (const p of [...pageDocs, ...flowDocs]) {
        const base = p.split("/").pop();
        if (!matrix.includes(base)) violations.push(`A7: ${rel(p)} is never referenced in 99-COVERAGE-MATRIX.md`);
      }
      const catalogPath = join(gitRoot, "docs", "plan", "05-USER-STORIES.md");
      if (existsSync(catalogPath)) {
        const catalog = readFileSync(catalogPath, "utf8");
        for (const s of new Set([...catalog.matchAll(/^- (US-\d+\.\d+)/gm)].map((m) => m[1]))) {
          if (!matrix.includes(`| ${s} `)) violations.push(`A7: catalog story ${s} has no row in 99-COVERAGE-MATRIX.md`);
        }
      }
    }

    // A8 built-claim paths (brace-globs like ui/{a,b}/ expand to one path per alternative)
    function expandBraces(path) {
      const m = path.match(/^(.*)\{([^}]+)\}(.*)$/);
      if (!m) return [path];
      return m[2].split(",").flatMap((alt) => expandBraces(`${m[1]}${alt.trim()}${m[3]}`));
    }
    for (const p of pageDocs) {
      readFileSync(p, "utf8").split("\n").forEach((line, i) => {
        if (!/\|\s*built\s*\|/.test(line)) return;
        const m = line.match(/`([^`]+\/)`/);
        if (!m) return;
        for (const path of expandBraces(m[1])) {
          if (!existsSync(join(gitRoot, path))) {
            violations.push(`A8: ${rel(p)}:${i + 1} claims built component at ${path} — path does not exist`);
          }
        }
      });
    }
  }

  // ---------- per page-tier spec bindings ----------
  for (const spec of pageSpecs) {
    const specRel = relative(CWD, spec);
    const bp = specBlueprintDoc(spec);
    if (!bp) { violations.push(`${specRel} is tier: page but carries no blueprint_doc: binding`); continue; }
    const docPath = join(gitRoot, bp);
    if (!existsSync(docPath)) { violations.push(`${specRel} binds blueprint_doc ${bp} — file does not exist`); continue; }
    const doc = readFileSync(docPath, "utf8");
    const dataSection = doc.split(/^## Data\s*$/m)[1]?.split(/^## /m)[0] ?? "";
    for (const gap of new Set([...dataSection.matchAll(/GAP-\d+|GAP-NEW/g)].map((x) => x[0]))) {
      violations.push(`${bp} ## Data cites ${gap} — the API slice must land before this page is coded`);
    }
  }

  // ---------- report ----------
  if (violations.length > 0) {
    process.stdout.write(`❌ ${RULE_ID} — ${violations.length} violation(s):\n`);
    for (const v of violations) process.stdout.write(`   - ${v}\n`);
    return 1;
  }
  const mode = locked ? `locked blueprint airtight (${pageDocs.length} pages, ${flowDocs.length} flows)` : "no lock, nothing gated";
  process.stdout.write(`✅ ${RULE_ID} — ${mode}; ${pageSpecs.length} page-tier spec(s) checked.\n`);
  return 0;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 5 — api-first (API_FIRST.yaml)
// ════════════════════════════════════════════════════════════════════════

function checkApiFirst(srcArg) {
  const GREEN = "\x1b[32m";
  const RED = "\x1b[31m";
  const RESET = "\x1b[0m";
  const NAME = "verify-api-first";
  const SKIP = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "coverage", "out", ".archive"]);

  function* walk(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) { if (!SKIP.has(e.name)) yield* walk(path.join(dir, e.name)); }
      else yield path.join(dir, e.name);
    }
  }
  const ok = (m) => { process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${m}\n`); return 0; };

  // Read a page-tier flag from a spec, routing through load-spec; fall back to
  // the dep-free line regex when the project `yaml` package is unavailable.
  const isPageSpec = (f) => {
    const loaded = loadSpec(path.dirname(f));
    if (loaded.ok && loaded.value && typeof loaded.value === "object") return loaded.value.tier === "page";
    return /^tier:\s*page\b/m.test(fs.readFileSync(f, "utf8"));
  };

  const srcRoot = path.resolve(process.cwd(), srcArg || "src");
  if (!fs.existsSync(srcRoot)) return ok("no src; nothing to verify.");

  // ui_discipline short-circuit
  for (const up of ["..", "../..", "../../.."]) {
    const auto = path.resolve(process.cwd(), up, ".standards", "autonomy.yaml");
    if (fs.existsSync(auto) && /^ui_discipline:\s*none\b/m.test(fs.readFileSync(auto, "utf8"))) return ok("ui_discipline: none — API-first gate n/a.");
  }

  const files = [...walk(srcRoot)];

  // page-tier present? (tier: page specs, or app/ route page files)
  const pageTier = files.some((f) =>
    (f.endsWith("spec.yaml") && isPageSpec(f)) ||
    (/\/app\/.*page\.(tsx|jsx)$/.test(f) && !/\/app\/page\.(tsx|jsx)$/.test(f) === false) ||
    /\/app\/.*\/page\.(tsx|jsx)$/.test(f)
  );
  if (!pageTier) return ok("no page-tier source yet — build APIs + flows first (API_FIRST.yaml).");

  const violations = [];
  const repoRoot = (() => {
    for (const up of [".", "..", "../.."]) {
      if (fs.existsSync(path.resolve(process.cwd(), up, ".git"))) return path.resolve(process.cwd(), up);
    }
    return path.resolve(process.cwd(), "../..");
  })();
  const attPath = path.join(repoRoot, "docs", "site", "MECHANICAL_COMPLETE.yaml");

  const flowFiles = files.filter((f) => /\/flows\/[^/]+\.flow\.yaml$/.test(f));
  const stems = flowFiles.map((f) => path.basename(f).replace(/\.flow\.yaml$/, ""));

  if (!fs.existsSync(attPath)) {
    violations.push(`page-tier source exists but ${path.relative(repoRoot, attPath)} is missing — the mechanical site must be attested 100% before UI (API_FIRST.yaml)`);
  } else {
    const att = fs.readFileSync(attPath, "utf8");
    if (!/mechanical-complete:\s*\d{4}-\d{2}-\d{2}\s+by:(user|agent)/.test(att)) {
      violations.push("attestation lacks the 'mechanical-complete: <date> by:(user|agent)' marker");
    }
    for (const stem of stems) {
      const m = att.match(new RegExp(`^\\s+${stem}:\\s*(\\S+)`, "m"));
      if (!m) { violations.push(`flow "${stem}" is not mapped in MECHANICAL_COMPLETE.yaml.flows — every flow must be E2E-mapped`); continue; }
      if (!fs.existsSync(path.join(repoRoot, m[1]))) violations.push(`flow "${stem}" maps to ${m[1]} which does not exist`);
    }
  }

  // mermaid per flow
  for (const f of flowFiles) {
    const stem = path.basename(f).replace(/\.flow\.yaml$/, "");
    const candidates = [f, f.replace(/\.flow\.yaml$/, ".flow.md"), path.join(path.dirname(f), "..", "spec.md")];
    const hasMermaid = candidates.some((c) => fs.existsSync(c) && fs.readFileSync(c, "utf8").includes("```mermaid"));
    if (!hasMermaid) violations.push(`flow "${stem}" has no mermaid diagram (flow.md sibling, flow.yaml, or spec.md) — FLOW_CONTRACT.yaml.mermaid_required`);
  }

  if (violations.length === 0) return ok(`page-tier permitted: ${stems.length} flow(s) attested E2E-mapped + diagrammed.`);
  process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.stderr.write("Per API_FIRST.yaml — the site must be 100% functional via APIs (flows E2E-green) before user-facing UI.\n");
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CLI dispatch
// ════════════════════════════════════════════════════════════════════════

// Optional positional source root (legacy `argv[2]`, default "src"). When a
// --check flag is present the positional arg lives after it; otherwise it is the
// first non-flag arg.
function sourceRootFromArgv() {
  const args = process.argv.slice(2);
  const checkIdx = args.indexOf("--check");
  const positional = args.filter((a, i) => {
    if (a === "--check") return false;
    if (checkIdx !== -1 && i === checkIdx + 1) return false;
    return !a.startsWith("--");
  });
  return positional[0] || "src";
}

const CHECKS = {
  "journeys": checkJourneys,
  "labs": checkLabs,
  "requirements": checkRequirements,
  "site-blueprint": checkSiteBlueprint,
  "api-first": checkApiFirst,
};

export function isCliInvocation(importMetaUrl, argv1) {
  if (argv1 === undefined || argv1 === "") return false;
  return importMetaUrl === pathToFileURL(argv1).href;
}

function main() {
  const args = process.argv.slice(2);
  const checkIdx = args.indexOf("--check");
  const only = checkIdx !== -1 ? args[checkIdx + 1] : null;
  const srcArg = sourceRootFromArgv();

  const names = only ? [only] : Object.keys(CHECKS);
  let failures = 0;
  for (const name of names) {
    const fn = CHECKS[name];
    if (!fn) {
      process.stderr.write(`verify-outside-in: unknown check "${name}" (expected one of: ${Object.keys(CHECKS).join(", ")})\n`);
      process.exit(2);
    }
    if (fn(srcArg) !== 0) failures += 1;
  }
  process.exit(failures > 0 ? 1 : 0);
}

if (isCliInvocation(import.meta.url, process.argv[1])) {
  main();
}
